e(value: Any) -> str:\",\"    value = materialize(value)\",\"    if value is NOTHING: return \\\"nothing\\\"\",\"    if isinstance(value, bool): return \\\"bool\\\"\",\"    if isinstance(value, int): return \\\"int\\\"\",\"    if isinstance(value, float): return \\\"float\\\"\",\"    if isinstance(value, str): return \\\"string\\\"\",\"    if isinstance(value, dict): return \\\"record<\\\" + \\\", \\\".join(f\\\"{k}: {nu_type(v)}\\\" for k, v in value.items()) + \\\">\\\"\",\"    if isinstance(value, list):\",\"        return \\\"list<any>\\\" if not value else f\\\"list<{nu_type(value[0])}>\\\"\",\"    return \\\"any\\\"\",\"\",\"\",\"def display_width(text: str) -> int:\",\"    return len(text)\",\"\",\"\",\"def table_render(value: Any) -> str:\",\"    value = materialize(value)\",\"    if isinstance(value, dict):\",\"        rows = [[str(key), scalar_text(item)] for key, item in value.items()]\",\"        aligns = [\\\"left\\\", \\\"left\\\"]\",\"        return grid(rows, None, aligns)\",\"    if isinstance(value, list) and value and all(isinstance(item, dict) for item in value):\",\"        columns = []\",\"        for row in value:\",\"            for key in row:\",\"                if key not in columns: columns.append(key)\",\"        headers = [\\\"#\\\"] + columns\",\"        rows = [[str(index)] + [scalar_text(row.get(key, NOTHING)) for key in columns] for index, row in enumerate(value)]\",\"        aligns = [\\\"right\\\"] + [\\\"right\\\" if all(isinstance(row.get(key), (int, float)) and not isinstance(row.get(key), bool) for row in value) else \\\"left\\\" for key in columns]\",\"        return grid(rows, headers, aligns)\",\"    rows = [[str(index), scalar_text(item)] for index, item in enumerate(value)]\",\"    numeric = all(isinstance(item, (int, float)) and not isinstance(item, bool) for item in value)\",\"    return grid(rows, None, [\\\"right\\\", \\\"right\\\" if numeric else \\\"left\\\"])\",\"\",\"\",\"def grid(rows: list[list[str]], headers: list[str] | None, aligns: list[str]) -> str:\",\"    all_rows = ([headers] if headers else []) + rows\",\"    widths = [max(display_width(row[i]) for row in all_rows) for i in range(len(all_rows[0]))]\",\"    def border(left: str, middle: str, right: str, fill: str = \\\"─\\\") -> str:\",\"        return left + middle.join(fill * (width + 2) for width in widths) + right\",\"    def line(row: list[str], header: bool = False) -> str:\",\"        cells = []\",\"        for i, text in enumerate(row):\",\"            align = \\\"left\\\" if header else aligns[i]\",\"            padded = text.rjust(widths[i]) if align == \\\"right\\\" else text.ljust(widths[i])\",\"            cells.append(f\\\" {padded} \\\")\",\"        return \\\"│\\\" + \\\"│\\\".join(cells) + \\\"│\\\"\",\"    output = [border(\\\"╭\\\", \\\"┬\\\", \\\"╮\\\")]\",\"    if headers:\",\"        output.extend([line(headers, True), border(\\\"├\\\", \\\"┼\\\", \\\"┤\\\")])\",\"    output.extend(line(row) for row in rows)\",\"    output.append(border(\\\"╰\\\", \\\"┴\\\", \\\"╯\\\"))\",\"    return \\\"\\\\n\\\".join(output) + \\\"\\\\n\\\"\",\"\",\"\",\"def command_words(text: str) -> list[str]:\",\"    tokens, words, start, depth = lex(text), [], 0, 0\",\"    current = []\",\"    for token in tokens[:-1]:\",\"        if token.value in \\\"[{(\\\": depth += 1\",\"        if token.value in \\\"]})\\\": depth -= 1\",\"        if current and depth == 0 and token.start > start and text[start:token.start].strip() == \\\"\\\":\",\"            words.append(text[current[0].start:current[-1].end])\",\"            current = []\",\"        current.append(token)\",\"        start = token.end\",\"    if current: words.append(text[current[0].start:current[-1].end])\",\"    return words\",\"\",\"\",\"class Shell:\",\"    COMMANDS = {\",\"        \\\"echo\\\", \\\"print\\\", \\\"open\\\", \\\"save\\\", \\\"ls\\\", \\\"pwd\\\", \\\"cd\\\", \\\"mkdir\\\", \\\"touch\\\", \\\"rm\\\", \\\"cp\\\", \\\"mv\\\",\",\"        \\\"get\\\", \\\"select\\\", \\\"reject\\\", \\\"where\\\", \\\"filter\\\", \\\"each\\\", \\\"enumerate\\\", \\\"flatten\\\", \\\"values\\\", \\\"columns\\\",\",\"        \\\"length\\\", \\\"first\\\", \\\"last\\\", \\\"skip\\\", \\\"take\\\", \\\"reverse\\\", \\\"sort\\\", \\\"sort-by\\\", \\\"uniq\\\", \\\"compact\\\",\",\"        \\\"from json\\\", \\\"to json\\\", \\\"from csv\\\", \\\"to csv\\\", \\\"from nuon\\\", \\\"to nuon\\\",\",\"        \\\"str upcase\\\", \\\"str downcase\\\", \\\"str trim\\\", \\\"str replace\\\", \\\"str contains\\\", \\\"str starts-with\\\", \\\"str ends-with\\\",\",\"        \\\"str length\\\", \\\"str join\\\", \\\"split row\\\", \\\"split chars\\\",\",\"        \\\"math sum\\\", \\\"math avg\\\", \\\"math min\\\", \\\"math max\\\", \\\"math round\\\", \\\"math sqrt\\\", \\\"math abs\\\", \\\"math floor\\\",\",\"        \\\"math ceil\\\", \\\"math median\\\", \\\"math mode\\\", \\\"math product\\\", \\\"math log\\\", \\\"describe\\\", \\\"into string\\\", \\\"into int\\\",\",\"        \\\"into float\\\", \\\"default\\\", \\\"append\\\", \\\"prepend\\\", \\\"wrap\\\", \\\"transpose\\\", \\\"group-by\\\", \\\"update\\\", \\\"insert\\\",\",\"    }\",\"\",\"    def __init__(self, stdin_enabled: bool = False):\",\"        self.variables: dict[str, Any] = {\\\"in\\\": StreamText(sys.stdin.buffer.read().decode(\\\"utf-8\\\", \\\"replace\\\")) if stdin_enabled else NOTHING}\",\"\",\"    def eval_script(self, script: str) -> Any:\",\"        result: Any = NOTHING\",\"        for statement in split_top(script, \\\";\\\"):\",\"            if not statement: continue\",\"            match = re.match(r\\\"^(?:let|mut|const)\\\\s+([\\\\w-]+)\\\\s*=\\\\s*(.*)$\\\", statement, re.S)\",\"            if match:\",\"                self.variables[match.group(1)] = self.eval_pipeline(match.group(2))\",\"                result = NOTHING\",\"                continue\",\"            match = re.match(r\\\"^\\\\$([\\\\w-]+)\\\\s*=\\\\s*(.*)$\\\", statement, re.S)\",\"            if match:\",\"                self.variables[match.group(1)] = self.eval_pipeline(match.group(2))\",\"                result = NOTHING\",\"                continue\",\"            result = self.eval_pipeline(statement)\",\"        return result\",\"\",\"    def eval_pipeline(self, text: str, locals_: dict[str, Any] | None = None) -> Any:\",\"        text = text.strip()\",\"        if text.startswith(\\\"if \\\"):\",\"            match = re.match(r\\\"if\\\\s+(.+?)\\\\s*\\\\{(.*?)\\\\}(?:\\\\s*else\\\\s*\\\\{(.*?)\\\\})?\\\\s*$\\\", text, re.S)\",\"            if match:\",\"                branch = match.group(2) if truthy(self.eval_pipeline(match.group(1), locals_)) else match.group(3)\",\"                return NOTHING if branch is None else self.eval_script(branch.strip())\",\"        segments = split_top(text, \\\"|\\\")\",\"        value: Any = NOTHING\",\"        for index, segment in enumerate(segments):\",\"            if index == 0 and not self.is_command(segment):\",\"                value = ExpressionParser(self, segment, locals_).parse()\",\"            else:\",\"                value = self.run_command(segment, value, locals_ or {})\",\"        return value\",\"\",\"    def is_command(self, segment: str) -> bool:\",\"        clean = segment.strip()\",\"        return any(clean == name or clean.startswith(name + \\\" \\\") for name in sorted(self.COMMANDS, key=len, reverse=True))\",\"\",\"    def arg(self, raw: str, locals_: dict[str, Any]) -> Any:\",\"        return self.eval_pipeline(raw, locals_)\",\"\",\"    def run_command(self, segment: str, value: Any, locals_: dict[str, Any]) -> Any:\",\"        words = command_words(segment)\",\"        if not words: return value\",\"        command, consumed = words[0], 1\",\"        for size in (2,):\",\"            candidate = \\\" \\\".join(words[:size])\",\"            if candidate in self.COMMANDS: command, consumed = candidate, size\",\"        args = words[consumed:]\",\"        flags = {a