ef grid(rows: list[list[str]], headers: list[str] | None, aligns: list[str]) -> str:","    all_rows = ([headers] if headers else []) + rows","    widths = [max(display_width(row[i]) for row in all_rows) for i in range(len(all_rows[0]))]","    def border(left: str, middle: str, right: str, fill: str = \"─\") -> str:","        return left + middle.join(fill * (width + 2) for width in widths) + right","    def line(row: list[str], header: bool = False) -> str:","        cells = []","        for i, text in enumerate(row):","            align = \"left\" if header else aligns[i]","            padded = text.rjust(widths[i]) if align == \"right\" else text.ljust(widths[i])","            cells.append(f\" {padded} \")","        return \"│\" + \"│\".join(cells) + \"│\"","    output = [border(\"╭\", \"┬\", \"╮\")]","    if headers:","        output.extend([line(headers, True), border(\"├\", \"┼\", \"┤\")])","    output.extend(line(row) for row in rows)","    output.append(border(\"╰\", \"┴\", \"╯\"))","    return \"\\n\".join(output) + \"\\n\"","","","def command_words(text: str) -> list[str]:","    tokens, words, start, depth = lex(text), [], 0, 0","    current = []","    for token in tokens[:-1]:","        if token.value in \"[{(\": depth += 1","        if token.value in \"]})\": depth -= 1","        if current and depth == 0 and token.start > start and text[start:token.start].strip() == \"\":","            words.append(text[current[0].start:current[-1].end])","            current = []","        current.append(token)","        start = token.end","    if current: words.append(text[current[0].start:current[-1].end])","    return words","","","class Shell:","    COMMANDS = {","        \"echo\", \"print\", \"open\", \"save\", \"ls\", \"pwd\", \"cd\", \"mkdir\", \"touch\", \"rm\", \"cp\", \"mv\",","        \"get\", \"select\", \"reject\", \"where\", \"filter\", \"each\", \"enumerate\", \"flatten\", \"values\", \"columns\",","        \"length\", \"first\", \"last\", \"skip\", \"tak